"""Tests for the stochastic-optimizer benchmark (run sgd_bench.py first)."""

import csv
from collections import defaultdict

import numpy as np

import sgd_bench

EXPECTED_ROWS = 3 * 3 * 30  # optimizers * seeds * epochs


def _load_results():
    rows = []
    with open("results.csv") as f:
        for r in csv.DictReader(f):
            rows.append((r["optimizer"], int(r["seed"]), int(r["epoch"]),
                         float(r["train_mse"])))
    return rows


def _per_epoch():
    series = defaultdict(lambda: defaultdict(list))  # opt -> seed -> [mse]
    for opt, seed, epoch, mse in _load_results():
        assert epoch == len(series[opt][seed]) + 1  # epochs contiguous, 1-based
        series[opt][seed].append(mse)
    return series


def test_results_shape_and_no_nan():
    rows = _load_results()
    assert len(rows) == EXPECTED_ROWS
    assert all(np.isfinite(mse) for *_ , mse in rows)
    opts = {r[0] for r in rows}
    seeds = {r[1] for r in rows}
    epochs = {r[2] for r in rows}
    assert opts == {"sgd", "momentum", "rmsprop"}
    assert seeds == {0, 1, 2}
    assert epochs == set(range(1, 31))


def test_final_mse_within_20pct_of_lstsq_floor():
    floor = sgd_bench.closed_form_mse()
    series = _per_epoch()
    for opt, seeds in series.items():
        final_mean = np.mean([vals[-1] for vals in seeds.values()])
        assert final_mean <= 1.2 * floor, (
            f"{opt}: final mean MSE {final_mean:.6f} > 1.2 * floor "
            f"{floor:.6f}")


def test_rmsprop_within_2x_floor_by_epoch_10():
    floor = sgd_bench.closed_form_mse()
    series = _per_epoch()
    for seed, vals in series["rmsprop"].items():
        assert len(vals) >= 10
        assert vals[9] <= 2.0 * floor, (
            f"rmsprop seed {seed}: MSE@10 {vals[9]:.6f} > 2 * floor")

